package com.example.starter.incident;

/**
 * 决策提案状态机：OPEN → EFFECTIVE 或 OPEN → EXPIRED。
 * EFFECTIVE（到期前达法定人数并原子写入任务变更）与 EXPIRED（到期未达法定人数）均为终态。
 */
public enum DecisionStatus {

    /** 投票中。 */
    OPEN,

    /** 已生效：到期前 SUPPORT 票达法定人数，任务变更已原子写入。 */
    EFFECTIVE,

    /** 已到期：到达 UTC 到期时刻仍未达法定人数。 */
    EXPIRED;
}

package com.example.starter.incident;

/**
 * 决策提案生效时原子写入的任务变更类型。
 */
public enum DecisionAction {

    /** 生效时将任务置为 DONE。 */
    COMPLETE,

    /** 生效时将任务置为 CANCELLED。 */
    CANCEL;
}

package com.example.starter.incident;

/**
 * 决策投票票型：支持或反对。同一角色对同一提案的同一任务版本仅一票。
 */
public enum VoteBallot {

    /** 支持票；CAST 状态的支持票计入法定人数。 */
    SUPPORT,

    /** 反对票；消耗该角色当次投票权但不计入法定人数。 */
    OPPOSE;
}

package com.example.starter.incident;

/**
 * 决策投票生命周期：CAST → WITHDRAWN（投票人撤回）或 CAST → STALE（任务版本变化失效）。
 * 仅 CAST 计入法定人数；WITHDRAWN 与 STALE 保留为历史证据，不物理删除。
 */
public enum VoteStatus {

    /** 有效票。 */
    CAST,

    /** 已撤回：投票人主动撤回，不再计入。 */
    WITHDRAWN,

    /** 已失效：提案涉及的任务版本变化后旧票失效，不计入新版本。 */
    STALE;
}

